\begin{subproof}
P(x) & hipótese\\
\begin{subproof}
\lnot P(x) & hipótese\\
\bot & $\lnot e$ 1, 2
\end{subproof}
\lnot \lnot P(x) & $\lnot i$ 2-3
\end{subproof}
P(x)\rightarrow \lnot \lnot P(x) & $\rightarrow i$ 1-4
\end{logicproof}

